package ug.audiocity.studio;
import java.io.*;import java.nio.*;import java.nio.file.*;
public class KeyTests {
 static int passed;static void check(boolean c,String m){if(!c)throw new AssertionError(m);passed++;}
 static Core.Source fixture(int root,boolean minor){int bpm=160;long bar=Core.beat(bpm)*4;float[] audio=new float[(int)(bar*8*2)];int[] degrees=minor?new int[]{0,5,2,6,0,3,6,0}:new int[]{0,4,3,0,5,4,3,0};for(int b=0;b<8;b++){float[] sound=PocketComposer.bar(1,root,minor,degrees[b],bpm,2,false);for(int i=0;i<sound.length;i++)audio[(int)(b*bar*2)+i]=sound[i];}return new Core.Memory(audio);}
 public static void main(String[] args)throws Exception{
  for(boolean minor:new boolean[]{false,true})for(int root=0;root<12;root++){KeyDetector.Result r=KeyDetector.analyse(fixture(root,minor));System.out.println("Source "+root+" "+minor+" => "+r.name()+" score="+r.score+" margin="+r.margin+" confidence="+r.confident);check(KeyDetector.mask(root,minor?2:1)==KeyDetector.mask(r.root,r.scale),"Transposed backing uses the expected allowed-note set: "+root+" "+minor);}
  boolean rejected=false;try{KeyDetector.analyse(new Core.Memory(new float[Core.RATE*6*2]));}catch(IOException e){rejected=true;}check(rejected,"Silent backing cannot force a key");boolean shortClip=false;try{KeyDetector.analyse(new Core.Memory(new float[Core.RATE*2]));}catch(IOException e){shortClip=true;}check(shortClip,"Short sources require manual selection");
  float[] noise=new float[Core.RATE*5*2];java.util.Random random=new java.util.Random(34);for(int i=0;i<noise.length;i++)noise[i]=(float)(random.nextGaussian()*.08);boolean unsafe=false;try{unsafe=KeyDetector.analyse(new Core.Memory(noise)).confident;}catch(IOException expected){}check(!unsafe,"Noise cannot silently select a confident song key");float[] single=Synth.note(60,4,Synth.factory(0));boolean oneNote=false;try{oneNote=KeyDetector.analyse(new Core.Memory(single)).confident;}catch(IOException expected){}check(!oneNote,"A single held note does not establish a confident song scale");
  Core.Session first=new Core.Session();first.tuneKey=9;first.tuneScale=1;first.tuneSpeed=2;first.tuneRange=1;first.tuneStrength=.76;first.tuneConfigured=true;Core.Session snapshot=first.copy();first.tuneKey=5;check(snapshot.tuneKey==9&&snapshot.tuneScale==1&&snapshot.tuneSpeed==2&&snapshot.tuneRange==1&&snapshot.tuneStrength==.76,"Undo snapshots isolate all vocal tuning settings");Core.Session fresh=new Core.Session();check(fresh.tuneKey==0&&fresh.tuneScale==0&&!fresh.tuneConfigured,"New song starts chromatic, not in the previous song key");File dir=Files.createTempDirectory("city-key-settings").toFile();snapshot.directory=dir.getPath();AudioIO.save(snapshot);Core.Session loaded=AudioIO.load(dir);check(loaded.tuneKey==9&&loaded.tuneScale==1&&loaded.tuneSpeed==2&&loaded.tuneRange==1&&loaded.tuneStrength==.76&&loaded.tuneConfigured,"Project save/load keeps song-specific tuning controls");ByteArrayOutputStream portable=new ByteArrayOutputStream();AudioIO.backup(portable,snapshot);File restoredDir=Files.createTempDirectory("city-key-backup").toFile();Core.Session restored=AudioIO.restore(new ByteArrayInputStream(portable.toByteArray()),restoredDir);check(restored.tuneKey==9&&restored.tuneScale==1&&restored.tuneConfigured,"Portable project backup carries the song key");for(File f:restoredDir.listFiles())f.delete();restoredDir.delete();org.json.JSONObject legacy=new org.json.JSONObject(new String(Files.readAllBytes(new File(dir,"session.json").toPath()),"UTF-8"));for(String field:new String[]{"tuneKey","tuneScale","tuneSpeed","tuneRange","tuneStrength","tuneConfigured"})legacy.remove(field);Files.write(new File(dir,"session.json").toPath(),legacy.toString().getBytes("UTF-8"));Core.Session resampled=AudioIO.retimeProject(snapshot,110,false);check(!resampled.tuneConfigured&&resampled.tuneScale==0,"Pitch-changing resampling clears a stale song key");Core.Session stretched=AudioIO.retimeProject(snapshot,110,true);check(stretched.tuneConfigured&&stretched.tuneKey==9,"Pitch-preserving tempo edits keep the correct key");Core.Session older=AudioIO.load(dir);check(older.tuneScale==0&&!older.tuneConfigured&&older.tuneStrength==1,"Older projects load with safe chromatic defaults");for(File f:dir.listFiles())f.delete();dir.delete();
  if(args.length>0){FloatBuffer data=ByteBuffer.wrap(Files.readAllBytes(Paths.get(args[0]))).order(ByteOrder.LITTLE_ENDIAN).asFloatBuffer();float[] audio=new float[data.remaining()];data.get(audio);KeyDetector.Result r=KeyDetector.analyse(new Core.Memory(audio));System.out.println("Supplied backing: "+r.name()+", score="+r.score+", gap="+r.margin+", confident="+r.confident);check(r.root==9&&r.scale==1&&r.confident,"Native key analysis agrees with independent analysis of supplied backing");}
  System.out.println(passed+" key detection and per-song settings checks passed.");
 }
}
